def resolve(path, cwd, links):
    def is_absolute(p):
        return p.startswith('/')

    def split_path(p):
        parts = p.split('/')
        return [part for part in parts if part and part != '.']

    def normalize_path(p):
        if not p:
            return '/'
        return p if p == '/' else p.rstrip('/')

    # Start with cwd if path is relative
    if not is_absolute(path):
        current = normalize_path(cwd)
    else:
        current = '/'

    # Split path into components
    components = split_path(path)

    # Track number of symlinks followed
    symlink_count = 0
    max_symlinks = 8

    i = 0
    while i < len(components):
        component = components[i]

        if component == '..':
            # Move to parent
            if current == '/':
                current = '/'
            else:
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
        else:
            # Append component
            if current == '/':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if current is a symlink
            canonical_current = normalize_path(current)
            if canonical_current in links:
                symlink_count += 1
                if symlink_count > max_symlinks:
                    return None

                target = links[canonical_current]

                # Resolve remaining components after this one
                remaining = components[i + 1:]

                # If target is absolute, start fresh from root
                if is_absolute(target):
                    current = '/'
                    target_components = split_path(target)
                else:
                    # Target is relative to the directory containing the link
                    if canonical_current == '/':
                        current = '/'
                    else:
                        current = canonical_current.rsplit('/', 1)[0]
                        if not current:
                            current = '/'
                    target_components = split_path(target)

                # Prepend target components to remaining components
                components = target_components + remaining
                i = 0
                continue

        i += 1

    result = normalize_path(current)
    return result if result else None

